head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

// 조회조건 결산일자

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function() {
    // 결산일자 조회

    $c.frame.path("../frame_head").fn_SrchAcntclsDt();
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_ProdBzCompst1_OnLoadError
 * @description dts_ProdBzCompst1 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ProdBzCompst1_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ProdBzCompst1);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00214.dts_ProdBzCompst1_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ProdBzCompst1_OnLoadCompleted
 * @description dts_ProdBzCompst1 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ProdBzCompst1_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_ProdBzCompst1.errorMsg) {
            alert(dts_ProdBzCompst1.errorMsg);
            return;
        }
        // 그리드 타이틀 세팅.
        await scwin.setGrdTitle();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00214.dts_ProdBzCompst1_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_ProdBzCompst2_OnLoadError
 * @description dts_ProdBzCompst2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_ProdBzCompst2_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_ProdBzCompst2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFIS00214.dts_ProdBzCompst2_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_ProdBzCompst2_OnLoadCompleted
 * @description dts_ProdBzCompst2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_ProdBzCompst2_OnLoadCompleted = function(rowcount) {
    try {
        if (dts_ProdBzCompst2.errorMsg) {
            alert(dts_ProdBzCompst2.errorMsg);
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFIS00214.dts_ProdBzCompst2_OnLoadCompleted" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name searchStdDt
 * @description 최근 3년 결산일자 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchStdDt = async function() {
    const sbmOptions = {
        id : "sbm_dts_ProdBzCompst1",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ProdBzCompst1=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name searchProdBzCompst
 * @description 제품및 사업구성 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.searchProdBzCompst = async function() {
    // Lodaing~~~ 표시
    const sbmOptions = {
        id : "sbm_dts_ProdBzCompst2",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_ProdBzCompst2=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initDs
 * @description 데이터셋 초기화.
 * @returns {void}
 * @hidden N
 */
scwin.initDs = function() {
    dts_ProdBzCompst1.removeAll();
    dts_ProdBzCompst2.removeAll();
};

/**
 * @method
 * @name chkValid
 * @description 조회조건 유효성 체크
 * @returns {void}
 * @hidden N
 */
scwin.chkValid = function() {
    // 필수항목 체크.

    scwin.vKisCd = $c.frame.path("../frame_head").fn_GetKisCd();

    scwin.vAcntclsDt = $c.frame.path("../frame_head").fn_GetAcntclsDt();
    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }
    return true;
};

/**
 * @method
 * @name search
 * @description 제품및 사업구성 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    // 데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크.
    if (!scwin.chkValid()) {
        return;
    }

    // Lodaing~~~ 표시

    // 최근 3년 결산일자 조회
    await scwin.searchStdDt();
};

/**
 * @method
 * @name setGrdTitle
 * @description 그리드 타이틀 세팅.
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setGrdTitle = async function() {
    $c.cm.setColumnProp(grd_ProdBzCompst, "TOT_AMT1", "Name", $c.stf.FormatDateEx(dts_ProdBzCompst1.getCellData(1, "STD_DT")));
    $c.cm.setColumnProp(grd_ProdBzCompst, "TOT_AMT2", "Name", $c.stf.FormatDateEx(dts_ProdBzCompst1.getCellData(2, "STD_DT")));
    $c.cm.setColumnProp(grd_ProdBzCompst, "TOT_AMT3", "Name", $c.stf.FormatDateEx(dts_ProdBzCompst1.getCellData(3, "STD_DT")));

    // 제품및 사업구성 조회
    await scwin.searchProdBzCompst();
};

/**
 * @method
 * @name excelDownload
 * @description 엑셀파일다운로드
 * @returns {void}
 * @hidden N
 */
scwin.excelDownload = function() {
    if (dts_ProdBzCompst2.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }
    $c.data.downloadGridViewExcel(grd_ProdBzCompst, {fileName: "제품및사업구성", type: "8"});
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_onload = function() {
    scwin.init();
};
